CREATE FUNCTION public.consume_post_slot(_user uuid,_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE anchor public.monthly_post_periods; used integer; credit uuid; BEGIN PERFORM 1 FROM public.profiles WHERE id=_user FOR UPDATE; SELECT * INTO anchor FROM public.monthly_post_periods WHERE user_id=_user; IF anchor.user_id IS NULL OR anchor.ends_at<=now() THEN INSERT INTO public.monthly_post_periods(user_id,starts_at,ends_at) VALUES(_user,now(),now()+interval '1 month') ON CONFLICT(user_id) DO UPDATE SET starts_at=excluded.starts_at,ends_at=excluded.ends_at RETURNING * INTO anchor; END IF; SELECT count(*) INTO used FROM public.monthly_post_usage WHERE user_id=_user AND used_at>=anchor.starts_at AND used_at<anchor.ends_at; IF used>=3 THEN SELECT id INTO credit FROM public.prime99_payments WHERE user_id=_user AND payment_purpose='extra_post' AND payable_amount=49 AND status='approved' AND used_post_id IS NULL ORDER BY received_at,id LIMIT 1 FOR UPDATE; IF credit IS NULL THEN RAISE EXCEPTION 'MONTHLY_THREE_POST_LIMIT'; END IF; UPDATE public.prime99_payments SET used_post_id=_id WHERE id=credit; END IF; INSERT INTO public.monthly_post_usage(post_id,user_id) VALUES(_id,_user); END $$;
REVOKE ALL ON FUNCTION public.consume_post_slot(uuid,uuid) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.guard_monthly_three_posts() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.consume_post_slot(NEW.user_id,NEW.id); RETURN NEW; END $$;
CREATE FUNCTION public.guard_service_post_quota() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.published AND (TG_OP='INSERT' OR NOT OLD.published) THEN PERFORM public.consume_post_slot(NEW.user_id,gen_random_uuid()); END IF; RETURN NEW; END $$;
CREATE TRIGGER service_post_quota BEFORE INSERT OR UPDATE ON public.service_profiles FOR EACH ROW EXECUTE FUNCTION public.guard_service_post_quota();
CREATE TABLE public.service_chat_pairs(member_id uuid NOT NULL REFERENCES public.profiles(id),owner_id uuid NOT NULL REFERENCES public.service_profiles(user_id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(member_id,owner_id));
GRANT SELECT ON public.service_chat_pairs TO authenticated; GRANT ALL ON public.service_chat_pairs TO service_role;
ALTER TABLE public.service_chat_pairs ENABLE ROW LEVEL SECURITY;
CREATE POLICY service_pair_participants ON public.service_chat_pairs FOR SELECT TO authenticated USING(auth.uid() IN(member_id,owner_id));
CREATE OR REPLACE FUNCTION public.can_post_chat(_post uuid DEFAULT NULL,_other uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND auth.uid()<>_other AND public.account_allowed(auth.uid()) AND public.account_allowed(_other) AND CASE WHEN _post IS NULL THEN _other=public.support_admin_id() OR public.has_role(auth.uid(),'admin') OR (public.has_prime99(auth.uid()) AND (EXISTS(SELECT 1 FROM public.service_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.messages WHERE post_id IS NULL AND ((sender_id=auth.uid() AND receiver_id=_other) OR (receiver_id=auth.uid() AND sender_id=_other))))) ELSE public.has_prime99(auth.uid()) AND EXISTS(SELECT 1 FROM public.post_chat_pairs WHERE post_id=_post AND ((member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other))) END $$;
CREATE FUNCTION public.ring_service(_owner uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; IF NOT public.has_prime99(auth.uid()) THEN RAISE EXCEPTION 'PAID_CHAT_REQUIRED'; END IF; IF auth.uid()=_owner OR NOT EXISTS(SELECT 1 FROM public.service_profiles WHERE user_id=_owner AND published) THEN RAISE EXCEPTION 'SERVICE_UNAVAILABLE'; END IF; INSERT INTO public.service_chat_pairs(member_id,owner_id) VALUES(auth.uid(),_owner) ON CONFLICT DO NOTHING; UPDATE public.profiles SET bell_activated_at=coalesce(bell_activated_at,now()) WHERE id=auth.uid(); IF public.can_notify(_owner) THEN INSERT INTO public.notifications(user_id,message) VALUES(_owner,'మీ సేవపై సమాచారం కోరారు; సంభాషణలో స్పందించండి.'); END IF; IF NOT EXISTS(SELECT 1 FROM public.messages WHERE sender_id=auth.uid() AND receiver_id=_owner AND post_id IS NULL) THEN INSERT INTO public.messages(sender_id,receiver_id,body) VALUES(auth.uid(),_owner,'హాయ్ · Hi'); END IF; RETURN _owner; END $$;
REVOKE ALL ON FUNCTION public.ring_service(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.ring_service(uuid) TO authenticated;
ALTER TABLE public.referral_board_consent ADD COLUMN district text NOT NULL DEFAULT '';
ALTER TABLE public.referral_board_consent ADD COLUMN district_group text NOT NULL DEFAULT '';
CREATE FUNCTION public.public_competition_areas() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('region',region,'district',district,'district_group',district_group,'score',score) ORDER BY score DESC),'[]'::jsonb) FROM (SELECT c.region,c.district,c.district_group,sum(r.joins) score FROM public.referral_vip_ranks() r JOIN public.referral_board_consent c ON c.user_id=r.user_id WHERE c.published AND c.region IN('TG','AP') AND c.district<>'' GROUP BY c.region,c.district,c.district_group) a $$;
REVOKE ALL ON FUNCTION public.public_competition_areas() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_competition_areas() TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.select_weekly_winners() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE wk date:=date_trunc('week',(now() AT TIME ZONE 'Asia/Kolkata'))::date; s timestamptz; e timestamptz; n integer:=0; r record; BEGIN IF now()<'2026-11-22 23:00:00+05:30'::timestamptz THEN RETURN 0; END IF; s:=(wk::timestamp AT TIME ZONE 'Asia/Kolkata'); e:=s+interval '7 days'; FOR r IN SELECT DISTINCT ON (c.region) c.region,st.user_id,st.joins,st.paid,st.percent,c.display_name,sp.photo_path FROM public.referral_payment_stats(s,e) st JOIN public.referral_board_consent c ON c.user_id=st.user_id JOIN public.service_profiles sp ON sp.user_id=st.user_id WHERE st.eligible AND c.region IN('TG','AP') AND c.published AND c.photo_consent AND sp.published AND sp.photo_path LIKE st.user_id::text||'/%' AND c.display_name<>'' ORDER BY c.region,st.joins DESC,st.paid DESC,st.user_id LOOP INSERT INTO public.weekly_winners(week_start,region,user_id,display_name,photo_path,joins,paid,percent) VALUES(wk,r.region,r.user_id,r.display_name,r.photo_path,r.joins,r.paid,r.percent) ON CONFLICT DO NOTHING; IF FOUND THEN n:=n+1; INSERT INTO public.notifications(user_id,message) VALUES(r.user_id,'అభినందనలు! మీరు ఈ వారం రాష్ట్ర విజేత; మీ పోస్టర్ చూడండి.'); END IF; END LOOP; RETURN n; END $$;
CREATE OR REPLACE FUNCTION public.weekly_winner_photo_ok(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.weekly_winners w JOIN public.referral_board_consent c ON c.user_id=w.user_id JOIN public.service_profiles s ON s.user_id=w.user_id WHERE w.photo_path=_path AND c.published AND c.photo_consent AND s.published AND s.photo_path=w.photo_path AND w.created_at>='2026-11-22 23:00:00+05:30'::timestamptz) $$;